contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Try to have a caller (this contract) invoke AdjustBetAmounts and observe bet limit.
    // Parameters:
    // newLimit: the value to attempt to set via AdjustBetAmounts
    // initialLimit: we will compare against the observed limit after the call
    function checkAdjustBetAmounts(uint256 newLimit, uint256 initialLimit) public {
        // read current bet limit
        uint256 before = c.currentBetLimit();

        // sanity precondition: caller assumes initialLimit equals observed before
        require(before == initialLimit);

        // Attempt to change bet limit by calling AdjustBetAmounts from this (non-owner) account
        // This will revert on the original contract (onlyOwner), but succeed on the mutant.
        // We perform the state-changing call as a top-level statement and capture whether it reverted.
        bool didRevert;
        // low-level call to detect revert without bubbling
        (bool ok, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", newLimit));
        didRevert = !ok;

        // read bet limit after attempt
        uint256 after = c.currentBetLimit();

        // Assert: if the attempt did not revert then after==newLimit would hold on mutant,
        // but on original the call must revert and thus bet limit must remain equal to before.
        // We assert the general rule that if a non-owner caller (this contract) tries to change
        // the bet limit and the call reverted, then the bet limit did not change.
        assert(didRevert ? (after == before) : true);
    }

    // allow contract to receive Ether if needed
    receive() external payable {}
}

