    function setUp() public { c = new C(address(this), 0); }

    // Fuzzed params: newLimit is the candidate bet limit an arbitrary caller will try to set;
    // caller is an arbitrary address that may or may not be the owner.
    function testFuzz_property(uint256 newLimit, address caller) public {
        // keep domain wide but avoid the zero-address for clarity (still allowed broadly)
        vm.assume(caller != address(0));

        // Ensure caller has some ETH to perform any payable interactions (not strictly needed here)
        vm.deal(caller, 1 ether);

        // Record current bet limit (should be initial 0 as constructed, but read via getter to follow rules)
