    function testFuzz_property(address caller, uint256 newLimit) public {
        // Keep domain wide but avoid zero-address caller which is ambiguous
        vm.assume(caller != address(0));

        // Capture original bet limit
        uint256 before = c.currentBetLimit();

        // Ensure caller has some ether so a payable call would be possible (not needed here,
        // but keeps scenarios realistic). Fund the caller.
        vm.deal(caller, 1 ether);

        // Owner (deployer of c in setUp) should be able to change betLimit to newLimit
        // so first perform as owner to establish the value can be set to newLimit legitimately
        c.AdjustBetAmounts(newLimit);
        uint256 setByOwner = c.currentBetLimit();

        // Now attempt same call as a non-owner (the fuzzed caller). We want the property:
        // "For every caller and amount, only owner can change betLimit" — thus a non-owner
        // call must NOT change currentBetLimit (it must remain what owner set).
        // Use try/catch to observe whether the call reverted or succeeded. Regardless, the
        // correct contract will not allow non-owner to change the value; the mutant will
        // allow some non-owner to change it.
        bool ok;
        try c.AdjustBetAmounts{gas: gasleft()}(newLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        // If caller is actually the owner (address(this) from setUp), then the call should succeed.
        // We need to ensure we're making the call as the fuzzed caller, not the test contract.
        // So perform the call under vm.prank to simulate the fuzzed caller.
        vm.prank(caller);
        // perform the call and ignore revert using try/catch to capture final value
        try c.AdjustBetAmounts(newLimit) {
            // do nothing
        } catch {
            // do nothing
        }

        uint256 after = c.currentBetLimit();

        // The universal property to assert: after a non-owner attempted AdjustBetAmounts(newLimit),
        // the contract's currentBetLimit must still equal the value previously set by the owner.
        // This is true for the reference contract for every caller and newLimit; the mutant that
        // removes onlyOwner will allow some non-owner to change betLimit, causing this assertion to fail.
        assertTrue(after == setByOwner);
    }
}

