pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // We fuzz a uint256 newBetLimit and an address caller to exercise owner vs non-owner behavior.
    function testFuzz_property(uint256 newBetLimit, address caller) public {
        // keep caller not equal to zero address to be meaningful EOA
        vm.assume(caller != address(0));

        // record difficulty before
        uint256 diffBefore = c.currentDifficulty();

        // Ensure caller has some ETH so they could send transactions if needed
        vm.deal(caller, 1 ether);

        // Attempt to call AdjustBetAmounts as the fuzzed caller.
        bool ok;
        vm.prank(caller);
        try c.AdjustBetAmounts(newBetLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call completes (either revert or success), difficulty must remain unchanged
        // in the correct contract for EVERY input; the mutant removing onlyOwner may allow a
        // non-owner to call and alter other state leading to a different difficulty for some inputs.
        uint256 diffAfter = c.currentDifficulty();

        // Single assertion: in the correct contract, difficulty never changes as a result of calling
        // AdjustBetAmounts (it only sets betLimit). This holds for all inputs; the mutant can violate it.
        assertTrue(diffBefore == diffAfter);
    }
}
